var lab = create("dsa", {"name":"prog","source":"#include <iostream>
using namespace std;
class Account {
private:
  int balance;
public:
  Account(int b) { balance = b; }
  void deposit(int x) { if (x > 0) balance += x; }
  int get() { return balance; }
};
int main() {
  Account a(100);
  a.deposit(50);
  a.deposit(-20);
  cout << a.get() << endl;
  return 0;
}
